metadata.er-schema:
{
  "title": "looply · 购物车 实体关系图",
  "version": "v1.0 · 2026-06-08",
  "tables": [
    {
      "name": "cart_item",
      "comment": "购物车项",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "user_id",
          "comment": "用户ID（登录用户，nullable）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "device_token",
          "comment": "匿名设备标识（cookie UUID，nullable）",
          "constraint": ""
        },
        {
          "name": "sku_id",
          "comment": "SKU ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "quantity",
          "comment": "数量（默认1）",
          "constraint": ""
        },
        {
          "name": "selected",
          "comment": "是否勾选（默认true，持久化）",
          "constraint": ""
        },
        {
          "name": "price_at_added",
          "comment": "加入时价格（用于价格变动提示）",
          "constraint": ""
        },
        {
          "name": "added_at",
          "comment": "加入时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "匿名用户通过 device_token 识别，登录后合并到 user_id；删除即硬删除；售罄由 SKU 实时判定"
    },
    {
      "name": "user",
      "comment": "用户（外部）",
      "columns": [
        {
          "name": "id",
          "comment": "用户ID",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "来自登录注册模块，购物车只读取 user_id"
    },
    {
      "name": "sku",
      "comment": "SKU（外部）",
      "columns": [
        {
          "name": "id",
          "comment": "SKU ID",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "来自商品模块，购物车读取 sku_id + 实时库存/上架状态"
    }
  ],
  "relations": [
    {
      "from": "cart_item",
      "to": "user",
      "type": "N:1",
      "label": "所属用户",
      "color": "#1565C0",
      "penwidth": 1.4
    },
    {
      "from": "cart_item",
      "to": "sku",
      "type": "N:1",
      "label": "关联SKU",
      "color": "#1565C0",
      "penwidth": 1.4
    }
  ],
  "design_rules": {
    "anonymous_cart": "匿名用户通过 device_token（cookie 存储的 UUID）识别，购物车数据存服务端，支持匿名阶段库存校验",
    "login_merge": "登录时将 device_token 关联的购物车项合并到 user_id 下：同一 SKU 已存在则保留已登录侧、删除匿名侧；不冲突则迁移",
    "owner_rule": "user_id 和 device_token 二选一非空：已登录用户 user_id 非空 + device_token 为空，匿名用户反之",
    "quantity_default_1": "二手单库存场景 quantity 默认为 1；字段保留是为了数据模型标准化和未来扩品类",
    "selected_persist": "selected 勾选状态持久化到数据库（default true），用户下次进入购物车保持上次勾选状态",
    "no_status": "无 status 字段，删除购物车项 = 硬删除行（无软删除需求）",
    "no_timeout_cleanup": "不做购物车超时清理，商品下架/售出后通过 SKU 实时状态自然变为 Sold Out",
    "sold_out_realtime": "售罄判定基于 SKU 实时库存/上架状态查询，不在 cart_item 表冗余存储",
    "price_at_added": "记录加入时价格，用于前端展示\"价格已变动\"提示（二手商品价格调整频繁）",
    "stock_recheck": "结算页两次库存校验：进入结算页时提示已售商品，下单时最终锁库存",
    "uk_user_sku": "唯一约束分两套：已登录 user_id + sku_id 联合唯一，匿名 device_token + sku_id 联合唯一"
  }
}
